class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def getDecimalValue(head):
    num = 0
    while head:
        # Shift bits left and add new digit
        num = (num << 1) | head.val
        head = head.next
    return num
